30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public LocalDate getRegistrationDate() {
61	        return this.registrationDate;
62	    }
63	
64	    public void setRegistrationDate(LocalDate registrationDate) {
65	        this.registrationDate = registrationDate;
66	    }
67	
68	    @PrePersist
69	    void defaultRegistrationDate() {
70	        if (this.registrationDate == null) {
71	            this.registrationDate = LocalDate.now();
72	        }
73	    }
74	
75	    public String getEmail() {
76	        return this.email;
77	    }
78	
79	    public void setEmail(String email) {
80	        this.email = email;
81	    }
82	
83	    public String getAddress() {
84	        return this.address;
85	    }
86	
87	    public void setAddress(String address) {
88	        this.address = address;
89	    }
90	
91	    public String getCity() {
92	        return this.city;
93	    }
94	
95	    public void setCity(String city) {
96	        this.city = city;
97	    }
98	
99	    public String getTelephone() {
100	        return this.telephone;
101	    }
102	
103	    public void setTelephone(String telephone) {
104	        this.telephone = telephone;
105	    }
106	
107	    protected Set<Pet> getPetsInternal() {
108	        if (this.pets == null) {
109	            this.pets = new HashSet<>();
110	        }
111	        return this.pets;
112	    }
113	
114	    protected void setPetsInternal(Set<Pet> pets) {
115	        this.pets = pets;
116	    }
117	
118	    public List<Pet> getPets() {
119	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
120	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
121	        return Collections.unmodifiableList(sortedPets);
122	    }
123	
124	    public void setPets(List<Pet> pets) {
125	        this.pets = new HashSet<>(pets);
126	    }
127	
128	    public void addPet(Pet pet) {
129	        getPetsInternal().add(pet);
130	        pet.setOwner(this);
131	    }
132	
133	    /**
134	     * Return the Pet with the given name, or null if none found for this Owner.
135	     *
136	     * @param name to test
137	     * @return true if pet name is already in use
138	     */
139	    public Pet getPet(String name) {
140	        return getPet(name, false);
141	    }
142	
143	    /**
144	     * Return the Pet with the given name, or null if none found for this Owner.
145	     *
146	     * @param name to test
147	     * @return true if pet name is already in use
148	     */
149	    public Pet getPet(String name, boolean ignoreNew) {
150	        name = name.toLowerCase();
151	        for (Pet pet : getPetsInternal()) {
152	            if (!ignoreNew || !pet.isNew()) {
153	                String compName = pet.getName();
154	                compName = compName.toLowerCase();
155	                if (compName.equals(name)) {
156	                    return pet;
157	                }
158	            }
159	        }
160	        return null;
161	    }
162	
163	    public Pet getPet(Integer petId) {
164	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
165	    }
166	
167	    @Override
168	    public String toString() {
169	        return new ToStringCreator(this)
170	
171	            .append("id", this.getId())
172	            .append("new", this.isNew())
173	            .append("lastName", this.getLastName())
174	            .append("firstName", this.getFirstName())
175	            .append("address", this.address)
176	            .append("city", this.city)
177	            .append("telephone", this.telephone)
178	            .toString();
179	    }
180	}
